// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        // Ensure caller has zero balance initially
        vm.assume(c.tokenBalance(caller) == 0);

        // Record balance before
        uint256 balanceBefore = c.tokenBalance(caller);

        // Call airDrop() as caller; it will revert if conditions not met (e.g., caller is not Bank contract for supportsToken check), but we care when it succeeds
        // We need to set up a Bank contract as caller to satisfy the supportsToken modifier
        // For simplicity, we can use vm.prank with a deployed Bank contract
        Bank bank = new Bank();
        vm.prank(address(bank));
        // The airDrop function uses msg.sender in supportsToken modifier; we need bank to call it
        // But the caller in the test is the one whose balance we check. Since supportsToken checks msg.sender, we must call as the bank.
        // Adjust: we call airDrop() from bank address, and check bank's tokenBalance.
        // Alternatively, rework: we will test that if airDrop succeeds, balance increases.
        // So we call via bank (which has supportsToken returning correct hash) and check bank's balance.

        // Actually, the problem: the caller must satisfy hasNoBalance and supportsToken. hasNoBalance checks msg.sender's tokenBalance.
        // So the caller should be an address that initially has zero tokenBalance and is a Bank contract with supportsToken returning Nu Token.
        // We create a Bank instance and set its tokenBalance to 0 initially (default). Then call as bank.
        c.airDrop();

        uint256 balanceAfter = c.tokenBalance(address(bank));
        assertTrue(balanceAfter > balanceBefore);
    }
}

contract Bank{
    function supportsToken() external pure returns (bytes32){
        return(keccak256(abi.encodePacked("Nu Token")));
    }
}

